public static class ReaderFeatureLogic {
 public static int HeadingAt(IReadOnlyList<OutlineHeading> headings,int paragraph){int lo=0,hi=headings.Count-1,answer=-1;while(lo<=hi){int mid=lo+(hi-lo)/2;if(headings[mid].Index<=paragraph){answer=mid;lo=mid+1;}else hi=mid-1;}return answer;}
 public static List<DisplayRow> Gather(FileResultContext context)=>context.Rows.Select(r=>new DisplayRow{Text=r.Hit!.Text,Words=r.Hit.Words,Hit=r.Hit,Context=context,Fill=Brushes.White}).ToList();
 public static string Copy(FileResultContext context)=>string.Join(Environment.NewLine+Environment.NewLine,context.Rows.Select(r=>r.Hit!.Text));
 public static (int Level,int Direction) Step(int[] levels,int level,int direction){if(levels.Length==0)return(level,direction);if(levels.Length==1)return(levels[0],direction);int at=Array.FindLastIndex(levels,n=>n<=level);at=Math.Max(0,at);if(at==0)direction=1;else if(at==levels.Length-1)direction=-1;return(levels[at+direction],direction);}
 public static void Verify(){var h=new[]{new OutlineHeading(2,0,"A"),new OutlineHeading(5,2,"B"),new OutlineHeading(12,0,"C")};if(HeadingAt(h,0)!=-1||HeadingAt(h,2)!=0||HeadingAt(h,11)!=1||HeadingAt(h,20)!=2)throw new InvalidOperationException("Heading synchronization regression");var step=Step(new[]{0,2},8,-1);if(step.Level!=0||Step(new[]{0,2},step.Level,step.Direction).Level!=2)throw new InvalidOperationException("Level folding regression");string text="بحث "+new string('x',900);var hit=new SearchHit{Path="reader.docx",Index=3,Text=text,Words=new[]{"بحث"},Length=1,Ticks=1};var context=new FileResultContext(new DisplayRow(),hit.Path,hit.Words,new[]{hit});var rows=Gather(context);if(rows.Count!=1||rows[0].Text!=text||Copy(context)!=text||rows[0].Hit!=hit)throw new InvalidOperationException("Full result text regression");}
}
