 readonly Popup outlineHistoryPopup=new(){StaysOpen=true,Placement=PlacementMode.Bottom};readonly WrapPanel historyCards=new();readonly List<string> outlineHistory=new();readonly string historyPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ElansaryWordLibrary","outline-history.json");
 readonly DispatcherTimer outlineSyncTimer=new(DispatcherPriority.Background){Interval=TimeSpan.FromMilliseconds(120)};bool syncingOutlineSelection,gatheredReader;int syncedOutlineIndex=-1,outlineVisibleLevel=8,outlineFoldDirection=-1,returnParagraph;int? requestedOutlineParagraph;Button? gatherButton;FileResultContext? gatheredContext;List<DisplayRow> gatheredRows=new();
