  inside.PreviewKeyDown+=async(_,e)=>{if(e.Key!=Key.Enter)return;e.Handled=true;EnsureFullReaderView(false);await Search(true);GatherReaderResults();};results.PreviewMouseLeftButtonUp+=(_,_)=>EnsureFullReaderView(false);results.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Enter)EnsureFullReaderView(false);};
