 }
 Button ReplaceViewerButton(string label,Func<Task> action){var old=viewerBar.Children.OfType<Button>().Single(b=>b.Content?.ToString()==label);int at=viewerBar.Children.IndexOf(old);viewerBar.Children.Remove(old);var replacement=LocalButton(viewerBar,label,action);viewerBar.Children.Remove(replacement);viewerBar.Children.Insert(at,replacement);return replacement;}
 void ToggleReaderResults(){if(gatheredReader){EnsureFullReaderView(true);return;}GatherReaderResults();}
 void GatherReaderResults(){var context=activeContext;if(current==null||context==null){status.Text="افتح ملفًا من نتائج البحث أولًا";return;}if(!gatheredReader)returnParagraph=VisibleDocumentParagraph()??current.Index;if(!ReferenceEquals(gatheredContext,context)){gatheredContext=context;gatheredRows=ReaderFeatureLogic.Gather(context);}gatheredReader=true;viewer.ItemsSource=gatheredRows;if(gatherButton!=null){gatherButton.Background=Brushes.LightGoldenrodYellow;gatherButton.ToolTip="اضغط لفرد المستند كاملًا؛ اضغط نتيجة لفتح مكانها";}viewerCaption.Text=$"{Path.GetFileName(context.Path)} — {context.Rows.Count} نتيجة كاملة داخل العارض — اضغط نتيجة لفرد موضعها";var row=gatheredRows.FirstOrDefault(r=>r.Hit!.Index==current.Index);if(row!=null){viewer.SelectedItem=row;viewer.ScrollIntoView(row);}QueueOutlineSync();}
 void EnsureFullReaderView(bool restore){if(!gatheredReader)return;gatheredReader=false;viewer.ItemsSource=paragraphs;if(gatherButton!=null){gatherButton.ClearValue(Control.BackgroundProperty);gatherButton.ToolTip="تجميع نتائج البحث الحالي داخل الملف";}if(activeContext!=null)viewerCaption.Text=$"{Path.GetFileName(activeContext.Path)} — {string.Join(" + ",activeContext.Words)} — {activeContext.Rows.Count} نتيجة";if(restore&&paragraphs.Count>0){int at=Math.Clamp(returnParagraph,0,paragraphs.Count-1);viewer.SelectedIndex=at;viewer.ScrollIntoView(paragraphs[at]);QueueOutlineSync(at);}}
 async Task CopyReaderResults(){var context=activeContext;if(context==null||context.Rows.Count==0){status.Text="لا توجد نتائج في الملف لنسخها";return;}string text=await Task.Run(()=>ReaderFeatureLogic.Copy(context));Clipboard.SetText(text);status.Text=$"تم نسخ {context.Rows.Count} نتيجة كاملة من {Path.GetFileName(context.Path)}";}
 void SyncReaderResult(){if(current==null||activeContext==null)return;if(gatheredReader){var row=gatheredRows.FirstOrDefault(r=>r.Hit!.Index==current.Index);if(row!=null){viewer.SelectedItem=row;viewer.ScrollIntoView(row);}}else if(current.Index<paragraphs.Count){viewer.SelectedIndex=current.Index;viewer.ScrollIntoView(paragraphs[current.Index]);}QueueOutlineSync(current.Index);}
 void SaveOutlineQuery(){string text=outlineQuery.Text.Trim();if(text.Length==0)return;outlineHistory.RemoveAll(s=>s.Equals(text,StringComparison.OrdinalIgnoreCase));outlineHistory.Insert(0,text);if(outlineHistory.Count>40)outlineHistory.RemoveRange(40,outlineHistory.Count-40);RenderOutlineHistory();try{Directory.CreateDirectory(Path.GetDirectoryName(historyPath)!);string temp=historyPath+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(outlineHistory));File.Move(temp,historyPath,true);}catch(Exception e){errors.Add(e.Message);}}
 void RenderOutlineHistory(){historyCards.Children.Clear();if(outlineHistory.Count==0){historyCards.Children.Add(new TextBlock{Text="لا يوجد سجل بعد. اكتب بحثًا ثم اضغط Enter.",TextWrapping=TextWrapping.Wrap,MaxWidth=235});return;}foreach(string text in outlineHistory){var b=new Button{Content=new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,MaxWidth=220},Margin=new Thickness(3),Padding=new Thickness(5),Background=Brushes.Honeydew};b.Click+=(_,_)=>{outlineQuery.Text=text;outlineQuery.CaretIndex=text.Length;};historyCards.Children.Add(b);}}
 void QueueOutlineSync(int? paragraph=null){requestedOutlineParagraph=paragraph;if(outlinePanel.Visibility!=Visibility.Visible||outlineHeadings.Count==0)return;if(!outlineSyncTimer.IsEnabled)outlineSyncTimer.Start();}
 int? VisibleDocumentParagraph(){var panel=FindVisual<VirtualizingStackPanel>(viewer);if(panel==null)return current?.Index;ListBoxItem? first=null;double top=double.PositiveInfinity;for(int i=0;i<VisualTreeHelper.GetChildrenCount(panel);i++){if(VisualTreeHelper.GetChild(panel,i) is not ListBoxItem item||!item.IsVisible)continue;try{double y=item.TransformToAncestor(viewer).Transform(new Point()).Y;if(y+item.ActualHeight>0&&y<viewer.ActualHeight&&y<top){top=y;first=item;}}catch(InvalidOperationException){}}if(first==null)return current?.Index;if(gatheredReader)return(first.Content as DisplayRow)?.Hit?.Index;int index=viewer.ItemContainerGenerator.IndexFromContainer(first);return index>=0?index:current?.Index;}
 static T? FindVisual<T>(DependencyObject root) where T:DependencyObject{if(root is T t)return t;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var found=FindVisual<T>(VisualTreeHelper.GetChild(root,i));if(found!=null)return found;}return null;}
 void SyncOutline(bool manual,int? paragraph=null){if(outlineDoc==null||!ReferenceEquals(outlineDoc,displayed))return;int at=ReaderFeatureLogic.HeadingAt(outlineHeadings,paragraph??VisibleDocumentParagraph()??0);int index=at>=0?outlineHeadings[at].Index:-1;if(index!=syncedOutlineIndex){syncedOutlineIndex=index;ApplyOutlineFilter();}var row=outlinePositions.FirstOrDefault(kv=>kv.Value==index).Key;if(row==null){if(manual&&index>=0)outlineInfo.Text="العنوان الحالي خارج نتائج بحث المخطط؛ امسح خانة بحث المخطط لإظهاره";return;}syncingOutlineSelection=true;try{outlineList.SelectedItem=row;if(outlinePanel.Visibility==Visibility.Visible)outlineList.ScrollIntoView(row);}finally{syncingOutlineSelection=false;}}
 void ApplyOutlineFilter(){var words=Core.Terms(outlineQuery.Text);var keep=new HashSet<int>();var stack=new List<OutlineHeading>();foreach(var h in outlineHeadings){while(stack.Count>0&&stack[^1].Level>=h.Level)stack.RemoveAt(stack.Count-1);stack.Add(h);bool include=words.Length>0?Core.Match(h.Text,words):h.Level<=outlineVisibleLevel||h.Index==syncedOutlineIndex;if(include)foreach(var ancestor in stack)keep.Add(ancestor.Index);}var rows=new List<DisplayRow>();syncingOutlineSelection=true;try{outlinePositions.Clear();foreach(var h in outlineHeadings){if(!keep.Contains(h.Index))continue;var row=new DisplayRow{Text=h.Text,Words=words,Indent=new Thickness(h.Level*12+4,2,0,2),Fill=h.Index==syncedOutlineIndex?Brushes.Khaki:h.Level==0?Brushes.Honeydew:Brushes.White};rows.Add(row);outlinePositions.Add(row,h.Index);}outlineList.ItemsSource=rows;var active=outlinePositions.FirstOrDefault(kv=>kv.Value==syncedOutlineIndex).Key;if(active!=null)outlineList.SelectedItem=active;}finally{syncingOutlineSelection=false;}if(outlineDoc!=null)outlineInfo.Text=outlineHeadings.Count==0?"لا يوجد مخطط تفصيلي معرف في المستند":$"العناوين: {rows.Count} من {outlineHeadings.Count} — حتى المستوى {outlineVisibleLevel+1}";}
